steps.command:
sbx run <<'EOF'
grep -rIl -e 'alpine' -e '2222' -e 'qemu' /etc /usr/local /opt /root /home 2>/dev/null | head -50
echo ===
ls -la /root /home /etc/init.d /etc/systemd/system 2>&1 | head -80
echo ===
cat /etc/inittab 2>/dev/null
echo ===
ls -la /usr/local/bin /opt/testbed-src
EOF

sbx run <<'EOF'
mkdir -p /tmp/iso
mount -o loop,ro /workspace/alpine.iso /tmp/iso 2>&1; echo "mount rc=$?"
ls -la /tmp/iso | head -40
echo === boot ===
ls -la /tmp/iso/boot 2>&1
echo === apks ===
find /tmp/iso -maxdepth 3 -name '*.apk' | head
echo === ssh ===
find /tmp/iso -maxdepth 4 -iname '*ssh*' | head
echo === setup scripts ===
ls -la /tmp/iso/usr/sbin/setup-* 2>/dev/null
EOF
